}

data "aws_iam_policy_document" "privesc15-PassExistingRoleToNewLambdaThenInvoke" {
  statement {
    effect = "Allow"
    actions = [
      "lambda:CreateFunction",
      "lambda:InvokeFunction",
      "iam:PassRole"
    ]
    resources = [
      "arn:aws:lambda:*:*:function:*",
      "arn:aws:iam::*:role/*"
    ]
  }
}

resource "aws_iam_policy" "privesc15-PassExistingRoleToNewLambdaThenInvoke" {
  name        = "privesc15-PassExistingRoleToNewLambdaThenInvoke"
  description = "Policy for privesc15-PassExistingRoleToNewLambdaThenInvoke"
